def bin_search(a, b, n):
    form = lambda x: math.floor((x/b)*a)
    looking = form(n)
    hi = n
    lo = 0

    while lo <= hi:
        if lo == hi:
            return lo
        elif lo == hi - 1:
            if form(lo) == looking:
                return lo
            else:
                return hi

        mid = (hi + lo) // 2
        if form(mid) < looking:
            lo = mid
        else:
            hi = mid

