    b1 = 0
    b2 = 0
    for i in range(LX):
        if X[i]:
            cnt += 1
            if pre:
                a1[i] = cnt
                b1 = cnt
            else:
                a1[i] = max(a1[i-1], cnt)
        else:
            pre = 0
            cnt = 0
            a1[i] = a1[i-1]
    pre = 1
    cnt = 0
    for i in range(LY):
        if Y[i]:
            cnt += 1
            if pre:
                a2[i] = cnt
                b2 = cnt
            else:
                a2[i] = max(a2[i-1], cnt)
        else:
            pre = 0
            cnt = 0
            a2[i] = a2[i-1]


    ra = LX-1
    rb = LY-1
    i = ra
    j = rb
    res = 0
    for _ in range(LX+LY):
