def sumDigits(x):
    if (x == 0):
        return 0 
    return x % 10 + sumDigits(x // 10)

def create(x):
    ans = ""
    while (x >= 9):
        ans = "9" + ans 
        x -= 9 
    ans = str(x) + ans 
    return int(ans)

def create_ex(x, y):
    track = -1
    for i in range(9, x + 1, 9):
        r = x - i 
        if (r + 1 == y):
            track = i 
    if (track == -1):
        return -1 
    r = x - track
    ans = 0  
    if (r < 9):
        ans = r 
    else: 
        ans = create(r - 8) * 10 + 8 
    ans *= (10 ** (track // 9))
    ans += create(track)
    return ans 

