class DSU(object):
    def __init__(self, n):
        self.father = list(range(n))
        self.size = n

    def union(self, x, s):
        x = self.find(x)
        s = self.find(s)
        if x == s:
            return
        self.father[s] = x
        self.size -= 1

    def find(self, x):
        xf = self.father[x]
        if xf != x:
            self.father[x] = self.find(xf)
        return self.father[x]


