def solve(n, a, b, s):
    dp = [[]] * 2
    for i in range(2):
        dp[i] = [0] * n
    dp[0][0] = (n + 1) * (a + b) - a
    dp[1][0] = inf
    for i in range(1, n):
        if s[i] == '1':
            dp[1][i] = min(dp[1][i - 1] + b, dp[0][i - 1] + a + 2 * b)
            dp[0][i] = inf
        else:
            dp[0][i] = min(dp[0][i - 1], dp[1][i - 1] + a)
            dp[1][i] = min(dp[1][i - 1] + b, dp[0][i - 1] + a + 2 * b)
    return dp[0][n - 1]
