def main():
    from types import GeneratorType
    def bootstrap(f, stack=[]):
        def wrappedfunc(*args, **kwargs):
            if stack:
                return f(*args, **kwargs)
            else:
                to = f(*args, **kwargs)
                while True:
                    if type(to) is GeneratorType:
                        stack.append(to)
                        to = next(to)
                    else:
                        stack.pop()
                        if not stack:
                            break
                        to = stack[-1].send(to)
                return to
        return wrappedfunc
    class Graph(object):

        def __init__(self):
            self.neighbours = {}

        def add_node(self, node):
            self.neighbours[node] = []

        def add_edge(self, edge):
            u, v = edge
            self.neighbours[u].append(v)
            self.neighbours[v].append(u)

        @bootstrap
        def dfs(self, v, parent, depth=0):
            parents[v] = parent
            depths[v] = depth
            visited[v] = 1
            intime[v] = timer[0]
            timer[0] += 1
            for child in self.neighbours[v]:
                if visited[child] == 0:
                    yield self.dfs(child, v, depth + 1)
            outtime[v] = timer[0]
            timer[0] += 1
            yield

    def inPath(x, y):
        return intime[x] <= intime[y] and outtime[x] >= outtime[y]

    g = Graph()
    n, q = map(int, input().split())
    for i in range(n):
        g.add_node(i + 1)
    for i in range(n - 1):
        x, y = map(int, input().split())
        g.add_edge((x, y))
    visited, intime, outtime = [0] * (n + 1), [0] * (n + 1), [0] * (n + 1)
    timer = [0]
    parents, depths = {}, {}
    g.dfs(1, -1)
    for i in range(q):
        lis = list(map(int, input().split()))[1:]
        deep = lis[0]
        for j in lis:
            if depths[deep] < depths[j]:
                deep = j
        for j in range(len(lis)):
            if lis[j] == deep:
                continue
            if parents[lis[j]]!=-1:
                lis[j] = parents[lis[j]]
        ok = True
        for j in lis:
            ok = ok & inPath(j, deep)
        print("YES") if ok else print("NO")






















