def solve(N, K, S):
    nxt = [0] * (N+1)
    cur = 1 << 30
    for i in xrange(N, 0, -1):
        if S[i-1] == '1':
            cur = i
        nxt[i] = cur

    dp = [0]
    for i in xrange(1, N+1):
        dp.append(dp[-1] + i)
        c = nxt[max(i-K, 1)]
        if c <= i+K:
            dp[i] = min(dp[i], dp[max(1,c-K)-1] + c)
    return dp[N]

