def binary_search(add, min_bound, max_bound, x_func, y_func, process_reply):
    while min_bound < max_bound:
        mid = (min_bound + max_bound - add) // 2
        x1, x2 = x_func(mid)
        y1, y2 = y_func(mid)
        reply = request(x1, y1, x2, y2)
        if process_reply(reply):
            max_bound = mid + add
        else:
            min_bound = mid + 1 + add
    return min_bound

def find_single_rectangle(x1, y1, x2, y2):
    xr = binary_search(0, x1, x2,
        lambda mid: (x1, mid),
        lambda mid: (y1, y2),
        lambda rep: rep == 1)   

    yr = binary_search(0, y1, y2,
        lambda mid: (x1, x2),
        lambda mid: (y1, mid),
        lambda rep: rep == 1)

    xl = binary_search(-1, x1, x2,
        lambda mid: (mid, x2),
        lambda mid: (y1, y2),
        lambda rep: rep == 0)

    yl = binary_search(-1, y1, y2,
        lambda mid: (x1, x2),
        lambda mid: (mid, y2),
        lambda rep: rep == 0)

    return xl, yl, xr, yr

def find_border(n):
    hor = binary_search(0, 1, n,
        lambda mid: (1, n),
        lambda mid: (1, mid),
        lambda rep: rep >= 1)
    if request(1, 1, n, hor) == 1 and request(1, hor + 1, n, n) == 1:
        return 1, 1, n, hor, 1, hor + 1, n, n
    ver = binary_search(0, 1, n,
        lambda mid: (1, mid),
        lambda mid: (1, n),
        lambda rep: rep >= 1)
    return 1, 1, ver, n, ver + 1, 1, n, n

