class Main:
    def __init__(self):
        self.buff = None
        self.index = 0

    def next(self):
        if self.buff is None or self.index == len(self.buff):
            self.buff = sys.stdin.readline().split()
            self.index = 0
        val = self.buff[self.index]
        self.index += 1
        return val

    def next_int(self):
        return int(self.next())

    def solve(self):
        n = self.next_int()
        fa = [-1 for _ in range(0, n)]
        nx = [i for i in range(0, n)]
        la = [i for i in range(0, n)]
        for _ in range(1, n):
            a = self.find(self.next_int() - 1, fa)
            b = self.find(self.next_int() - 1, fa)
            fa[a] = b
            nx[la[b]] = a
            la[b] = la[a]
        ii = 0
        while fa[ii] != -1:
            ii += 1
        ans = []
        for _ in range(0, n):
            ans.append(str(ii + 1))
            ii = nx[ii]
        print(' '.join(ans))

    def find(self, k, fa):
        if fa[k] == -1:
            return k
        fa[k] = self.find(fa[k], fa)
        return fa[k]


