def consume(r, l, p1, p2, p3, t1, t2):
    if l - r <= t1:
        return p1 * (l-r)
    elif t1 < l - r <= t1 + t2:
        return p1 * t1 + p2 * (l-r-t1)
    elif l - r > t1 + t2:
        return p1 * t1 + p2 * t2 + p3 * (l-r-t1-t2)

