def minimum_steps(total, letter):
	index=-1
	ret=0
	while True:
		if index+1==total:
			break
		else:
			index+=1
		if index==0:
			if letter[0]=='0':
				continue
			else:
				ret=1
		else:
			if letter[index]=='0' and letter[index-1]==letter[index]:
				continue
			else:
				ret+=1

	if letter[total-1]=='0' and ret!=0:
		ret-=1
	return ret
