        :type intervals: List[Interval]
        :rtype: List[Interval]
        """
        intervals = sorted(intervals, key=lambda x: x[0])
        n=len(intervals)
        if n==0:
            return []
        re=[]
        re.append(intervals[0])
        for i in range(1,n):
            a=re[-1]
            b=intervals[i]
            if b[0]>a[1]:
                re.append(b)
            else:
                re[-1][1]=max(a[1],b[1])
        return re

