from decimal import Decimal


def dist(a, b):
    x1, y1 = a
    x2, y2 = b
    return Decimal((x1-x2)**2+(y1-y2)**2).sqrt()


def minh(a, b, c):
    m = dist(a, b)
    n = dist(b, c)
    k = dist(a, c)
    p = Decimal(m + n + k)/2
    sqp = (p*(p-m)*(p-n)*(p-k)).sqrt()
    hm = (Decimal(2)/m)*sqp
    hn = (Decimal(2)/n)*sqp
    hk = (Decimal(2)/k)*sqp
    return min([hm, hn, hk])


