        k = (last // l) * l + l * i
        digsum = startdigsum - omitsum + i
        diff = bnum - digsum
        r = getnum(diff)
        if diff >= 0 and len(str(r)) <= len(str(l // 10)):
            return r + k
        if diff < 0:
            l *= 10
            i = 1
