def p1(x):
    if x % 2 == 0:
        x, y = x / 2, x + 1
    else:
        y = (x + 1) / 2

    return x*y


def p2(x):
    y, z = x + 1, 2*x + 1

    if x % 2 == 0:
        x /= 2
    else:
        y /= 2

    if z % 3 == 0:
        z /= 3
    elif x % 3 == 0:
        x /= 3
    else:
        y /= 3

    return x * y * z


def is_prime(x):
    i = 2
    while i*i <= x:
        if x % i == 0:
            return False
        i += 1

    return True


