from math import sqrt

def primeFactor(n):
    ret, i, d, sq = {}, 2, 2, int(sqrt(n)) + 1
    while i < 4:
        k = 0
        while n % i == 0:
            n, k = n//i, k+1
            ret[i], sq = k, int(sqrt(n)) + 1
        i = i * 2 - 1
    while i <= sq:
        k = 0
        while n % i == 0:
            n, k = n//i, k+1
            ret[i], sq = k, int(sqrt(n)) + 1
        i, d = i + d, d ^ 6
    if n > 1: ret[n] = 1
    return ret

def divisors(N):
    pf = primeFactor(N)
    ret = [1]
    for p in pf:
        prev = ret[:]
        q = 1
        for i in range(1, pf[p]+1):
            q *= p
            for r in prev:
                ret.append(r * q)
    return sorted(ret)

def chk(X):
    n = len(X)
    XX = X * 2
    mi = 1 << 30
    for d in divisors(n):
        if d >= mi: break
        for i in range(d):
            for j in range(i, n+i, d):
                if XX[j] != XX[j+d]:
                    break
            else:
                mi = min(mi, d)
    return mi

