def bscheck(n, l, v1, v2, k, t):
    while True:
        if k > n:
            k = n
        if n == 0:
            return True
        if l / v2 > t:
            return False
    #    v2 * tx + v1 * (t - tx) = l
    #    (v2 - v1) * tx = l - v1 * t
        tx = (l - v1 * t) / (v2 - v1)
        ty = (tx * v2 - tx * v1) / (v1 + v2)

        _n = n - k
        _l = l - tx * v1 - ty * v1
        _t = t - tx - ty

        n = _n
        l = _l
        t = _t


