class Game:
    def __init__(self, n, x, y):
        self.n = n
        self.x = x
        self.y = y

    def ask(self, ps):
        print('? ' + str(len(ps)) + ' ' + ' '.join(str(p + 1) for p in ps), flush=True)
        res = int(input().strip())
        return res == self.y or res == self.x ^ self.y

    def mask_by_bit(self, b):
        return [i for i in range(self.n) if (i & 2 ** b) != 0]

    def same_bit(self, b):
        ps = self.mask_by_bit(b)
        if len(ps) == 0:
            return True
        return not self.ask(ps)

    def filter_out(self, ps):
        if len(ps) == 1:
            return ps[0]
        first_part = ps[:len(ps) // 2]
        second_part = ps[len(ps) // 2:]
        if self.ask(first_part):
            return self.filter_out(first_part)
        else:
            return self.filter_out(second_part)


