        move(table, t)
    solve2m(n1, m1 + 1, n, m, table)


def solve(n1, m1, n, m, table):
    if n - n1 == 2:
        solve2m(n1, m1, n, m, table)
        return
    for j in range(0, m - 1):
        if table[n1][j] == 1:
            t = (n1, j, n1 + 1, j, n1 + 1, j + 1)
            move(table, t)
    if table[n1][m - 1] == 1:
        t = (n1, m - 1, n1 + 1, m - 1, n1 + 1, m - 2)
        move(table, t)
    solve(n1 + 1, m1, n, m, table)

