from collections import deque

def subtree_specs(graph, d, node, visited, edges_dict, res_edges):
    num_ones = 0
    for nb in graph[node]:
        if not visited[nb]:
            visited[nb] = True
            res = subtree_specs(graph, d, nb, visited, edges_dict, res_edges)
            if res % 2 == 1:
                # Need to attach this node
                res_edges.append(edges_dict[node][nb])
            num_ones += res
    if d[node] == 1:
        num_ones += 1
    return num_ones

def subtree_specs_stack(graph, d, edges_dict):
    n = len(graph)
    visited = n * [False]
    visited[0] = True
    children = [[] for _ in range(n)]
    num_ones = n * [-1]
    res_edges = []
    q = deque([(0, 'InProcess')])
    while len(q) > 0:
        node, state = q.pop()
        if state == 'InProcess':
            q.append((node, 'Done'))
            for nb in graph[node]:
                if not visited[nb]:
                    visited[nb] = True
                    q.append((nb, 'InProcess'))
                    children[node].append(nb)
        elif state == 'Done':
            res = sum([num_ones[i] for i in children[node]])
            if d[node] == 1:
                res += 1
            num_ones[node] = res
            for child in children[node]:
                if num_ones[child] % 2 == 1:
                    res_edges.append(edges_dict[node][child])
    return res_edges

