def can(s, n):
    if n == 0:
        return ""

    cs = list(map(int, s))
    was_over = [False for i in range(n)]
    ans = [0 for i in range(n)]
    i, j = 0, n - 1
    last = int(n == len(cs) - 1)
    while i < j:
        need_a = last * 10 + cs[i]
        need_b = last * 10 + cs[j]
        if last == 1 and cs[i] == 9 and cs[j] == 0:
            need_a = 9
            need_b = 10
        if abs(need_a - need_b) > 1:
            return ""
        if need_a == need_b + 1:
            return ""
        if need_a == need_b == 19:
            return ""

        if need_a >= 10:
            ans[j] = 9
            ans[i] = need_a - 9
        else:
            ans[j] = need_a
            ans[i] = 0

        if need_a >= 10 or was_over[i]:
            cs[i + 1] = (cs[i + 1] - 1) % 10
            if cs[i + 1] == 9:
                was_over[i + 1] = True

        last = (need_b == need_a + 1)

        i += 1
        j -= 1

    if i == j:
        need = last * 10 + cs[i]
        if need % 2 != 0:
            return ""
        ans[i] = need // 2

    if int("".join(map(str, ans))) + int("".join(map(str, reversed(ans)))) != int("".join(map(str, reversed(s)))):
        return ""

    return "".join(map(str, reversed(ans)))


