            ps.add(memo[k])

        if s == -1 and len(ps) == 2:
            memo[t] = sum(ps) + 2
            return memo[t]

        if len(ps) > 1:
            return -t

        if len(ps) == 0:
            memo[t] = 0
            return 0

        memo[t] = list(ps)[0] + 1
        return memo[t]

    def _path(tt,ss):
