    train = {}
    while True:
        far = 0
        for i in candies:
            if i[0] == start:
                if i[1] < start:
                    far = max(far,i[1]+n)
                else:
                    #print(far,i[1])
                    far = max(far,i[1])

        if far != 0:
            if far > n:
                far -= n
            i = (start,far)
            if i not in train.keys():
                train[i] = 1
            else:
                train[i] += 1
        new = []
        for i in candies:
            if i[1] == start:
                if i in train.keys():
                    train[i] -= 1
                    if train[i] == 0:
                        del train[i]
                else:
                    new.append(i)
            else:
                new.append(i)

        candies = new[:]
        #print(candies,train,start)
        if not candies:
            break
        time += 1
        start += 1
        if start == n+1:
            start = 1


