def query(n, k, x):
	if k == 0: return 0
	if k == n: return 1
	if n % 2 == 0:
		evens = max(2, n - 2*k + 2)
		odds = n + 1
		k -= n/2
		if k > 0:
			odds = n - 1 - 2*k + 2
		if x % 2 == 0:
			return int(x >= evens)
		else:
			return int(x >= odds)
	else:
		if x == n: return 1
		k -= 1
		evens = max(2, n - 1 - 2*k + 2)
		odds = n + 1
		k -= n/2
		if k > 0:
			odds = n - 2 - 2*k + 2
		if x % 2 == 0:
			return int(x >= evens)
		else:
			return int(x >= odds)

