def dfs(dp,node,edges,s,visited):
    stack = [node]
    while stack:
        node = stack[-1]
        if node not in visited:
            count = 0
            for kid in edges[node]:
                if kid in visited:
                    count += 1
                stack.append(kid)

            if count == len(edges[node]):
                for kid in edges[node]:
                    for i in xrange(26):
                        dp[node][i] = max(dp[node][i],dp[kid][i])

                dp[node][ord(s[node-1])-ord('a')] += 1
                visited.add(node)
                stack.pop()
        else:
            stack.pop()

def dfs2(edges,node,visited,recursion_stack):
    stack = [node]
    while stack:
        node = stack[-1]
        visited.add(node)
        recursion_stack.add(node)
        count = 0
        for kid in edges[node]:
            if kid not in visited:
                stack.append(kid)
            elif kid in recursion_stack:
                return True
            else:
                count += 1

        if count == len(edges[node]):
            stack.pop()
            recursion_stack.remove(node)

    return False


def cycle(edges,n):
    visited = set()
    recursion_stack = set()
    for i in xrange(1,n+1):
        if i not in visited:
            if dfs2(edges,i,visited,recursion_stack):
                return True

    return False

