def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b

def cal((f1, k1), (f2, k2)):
    if f1 > f2:
        f1, k1, f2, k2 = f2, k2, f1, k1
    A = (f1 - f2) % k2
    B = 0
    x1 = 0
    k11 = k1 % k2
    k1x1 = 0
    while B != A and k1x1 <= f1:
        if B < A:
            dx1 = (A - B) // k11
        else:
            dx1 = (A + k2 - B) // k11
        dx1 = max(dx1, 1)
        B = (B + k11 * dx1) % k2
        x1 += dx1
        k1x1 += k1 * dx1
    f = f1 - k1x1
    if f <= 0:
        return (0, 1)
    k = lcm(k1, k2)
    return (f, k)

