class String2:
    def __init__(self, s, b=None):
        if b is not None:
            self.b = b
            return
        self.b = [0] * 26
        for i in s:
            self.b[ord(i) - ord('a')] += 1

    def __add__(self, other):
        b = self.b.copy()
        for i in range(26):
            b[i] += other.b[i]
        return String2('', b)

    def __sub__(self, other):
        b = self.b.copy()
        for i in range(26):
            b[i] -= other.b[i]
        return b

    def __mul__(self, other):
        ans = String2('', self.b)
        for i in range(26):
            ans.b[i] *= other
        return ans



