def input_as_list():
    return list(map(int, input().split()))

def array_of(f, *dim):
    return [array_of(f, *dim[1:]) for _ in range(dim[0])] if dim else f()

def build_binary_lifting_array(tree):
    """ Tree is represented as parent of node n = tree[n].

        Parent of the root node should be -1.
    """

    def array_of(f, *dim):
        return [array_of(f, *dim[1:]) for _ in range(dim[0])] if dim else f()

    size = len(tree)
    max_depth = size.bit_length()

    result = array_of(lambda:-1, max_depth, size)
    result[0] = list(tree)

    for depth in range(1, max_depth):
        for node in range(0, size):
            try:
                result[depth][node] = result[depth - 1][result[depth - 1][node]]
            except:
                pass

    return result

def main():
    n, m = input_as_list()
    segs = [input_as_list() for _ in range(n)]
    queries = [input_as_list() for _ in range(m)]

    MAX = 500001
    if DEBUG: MAX = 101

    endpoints = array_of(lambda: -1, MAX)
    for s, e in segs:
        endpoints[s] = max(endpoints[s], e)

    cur_max = -1
    for i, e in enumerate(endpoints):
        if cur_max <= i:
            cur_max = -1
        cur_max = max(cur_max, e)
        endpoints[i] = cur_max

    blt = build_binary_lifting_array(endpoints)
    debug_print(*blt, sep='\n')

    max_depth = len(blt)
    pow2 = [1, 1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024,
            2048, 4096, 8192, 16384, 32768, 65536, 131072,
            262144, 524288]
    out = []
    for s, e in queries:
        cnt, depth = 0, 0

        while True:
            if blt[depth][s] == -1:
                if depth == 0:
                    if s < e: cnt = -1
                    break
                else:
                    s = blt[depth-1][s]
                    depth = 0
            elif blt[depth][s] == e:
                cnt += pow2[depth]
                break
            elif blt[depth][s] > e:
                if depth == 0:
                    cnt += 1
                    break
                else:
                    s = blt[depth-1][s]
                    depth = 0
            else:
                cnt += pow2[depth]
                if depth == max_depth-1:
                    s = blt[depth][s]
                    depth = 0
                else:
                    depth += 1

        out.append(str(cnt))

    print('\n'.join(out))

