    a = [ getNum() for _ in RANGN ]

    revlis = []
    g = [MAXA]*n
    for i in reversed(RANGN):
        x = -a[i]
        pt = binsleft( g, x )
        revlis.append(pt+1)
        if( x < g[pt] ):
            g[pt] = x
    hlis = max( revlis )

    lis, inlis = [], []
    d = [0]*n
    for i in RANGN: g[i] = MAXA
    for i in RANGN:
        pt = binsleft( g, a[i] )
        lis.append( pt+1 )
