class Ball:
    def __init__(self, x, v, m):
        self.v = v
        self.x = x
        self.m = m

    def move(self, time):
        self.x += self.v * time

    def collisionTime(self, other):
        if self.v == other.v:
            return float("inf")

        t = - (self.x - other.x) / (self.v - other.v)

        if t < 1e-9:
            return float("inf")
        return t 

    def __str__(self):
        return "Ball(x={:.2f} v={:.2f} m={:.2f})".format(self.x, self.v, self.m)


