def bfs(graph, start=0):
    used = [False] * len(graph)
    used[start] = True
    dist = [0] * len(graph)
    q = [start]
    for v in q:
        for w in graph[v]:
            if not used[w]:
                dist[w] = dist[v] + 1
                used[w] = True
                q.append(w)
    return dist, q[-3:]


