        push_c(cnt, u, i)
        push_c(cnt, v, i)
        push_c(cnt, w, i)

    U = Union(n)
    deg0 = [x for x, num in cnt.items() if len(num) == 1]

    while len(deg0) > 0:
        u = deg0.pop()
        process(cnt, tup, deg0, order, g, U, u)

    used = [0] * (n-2)   
