def z_function(s):
    n = len(s)
    l = 0
    r = 0
    z = [0 for x in range(n)]
    for i in range(1, n):
        z[i] = max(0, min(r - i, z[i - l]))
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l = i
            r = i + z[i]
    return z


