def ask(a0,b0,L):
    print("?",L,L,flush=True)
    aa=[i for i in range(a0,a0+L)]
    print(*aa,flush=True)
    aa=[i for i in range(b0,b0+L)]
    print(*aa,flush=True)
    return input()

def main():
    for _ in range(int(input())):
        n,k=map(int,input().split())
        isfirst=False
        for _ in range(30):
            if ask(1,randrange(2,n+1),1)=="SECOND":
                isfirst=True
        if isfirst:
            print("! 1",flush=True)
            continue

        ln=1
        while 1:
            ret=ask(1,1+ln,ln)
            if ret=="FIRST":
                l,r=1+ln,1+ln*2
                break
            if ln*4>n:
                l,r=1+ln*2,n+1
                break
            ln*=2

        while l+1<r:
            m=(l+r)//2
            if ask(1,l,m-l)=="EQUAL":l=m
            else:r=m

        print("!",l,flush=True)

