                len_v = max_child[v][0] + 1
                if len_v > chlen[0]:
                    chlen[1] = chlen[0]
                    chlen[0] = len_v
                elif len_v > chlen[1]:
                    chlen[1] = len_v
            for v in adj[u]:
                if v == p:
