        dp[0][1] = 0
    elif input_str[0] == '1':
        dp[0][0] = 0
        dp[0][1] = 1
    else:
        dp[0][0] = 1
        dp[0][1] = 1

    ans += max(dp[0][1], dp[0][0])

    for i in range(1, n):
        if input_str[i] == '0':
            dp[i][1] = 0
            dp[i][0] = dp[i - 1][1] + 1
        elif input_str[i] == '1':
            dp[i][0] = 0
            dp[i][1] = dp[i - 1][0] + 1
        else:
            dp[i][0] = dp[i - 1][1] + 1
            dp[i][1] = dp[i - 1][0] + 1

        ans += max(dp[i][1], dp[i][0])

    return ans



