def is_square(n):
    return int(n ** 0.5) ** 2 == n

def solve(n):
    if n <= 3:
        return range(2, n+1)

    k = n >> 1
    if n % 4 == 0:
        return [k]
    if n % 4 == 1:
        return [k, n]
    if n % 4 == 2:
        if is_square(n + 2):
            return [k + 1]
        if is_square(2 * k * (k - 1)):
