def absorb(astronauts, power, count, double, triple):
    astronauts = astronauts.copy()

    while astronauts:
        a = astronauts[-1]

        if power > a:
            power += a // 2
            count += 1
            astronauts.pop()
        else:
            if not double and not triple:
                return count

            times_2 = 0
            times_3 = 0
            times_4 = 0
            times_6 = 0
            times_12 = 0

            if double > 0:
                times_2 = absorb(astronauts, power * 2, count, double - 1, triple)
            if double > 1:
                times_4 = absorb(astronauts, power * 4, count, double - 2, triple)
            if triple > 0:
                times_3 = absorb(astronauts, power * 3, count, double, triple - 1)
            if double > 0 and triple > 0:
                times_6 = absorb(astronauts, power * 6, count, double - 1, triple - 1)
            if double > 1 and triple > 0:
                times_12 = absorb(astronauts, power * 12, count, double - 2, triple - 1)

            return max(times_2, times_3, times_4, times_6, times_12)

    return count


