    for i in range(length-2, -1, -1):
        diff = nums[i+1]-nums[i]
        idxs[i] = min(length, idxs[i+1]+diff)

    for i in range(length):
        idxs[i] -= (length-1-i)

    from collections import defaultdict
    num2i = defaultdict(set)

    bad = [False] * (length+1)
    for i in range(prime, length+1, prime):
        bad[i] = True

    flag = False
