class SplayTree():
	def __init__(self):
		self.children={}
		self.parents={}
		self.root=None
	def insert(self, x):
		if self.root is None:
			self.root=x
			self.children[x]=[None,None]
			self.parents[x]=None
		else:
			curr = self.root
			while True:
				if curr == x:
					self.splay(x)
					return None
				elif x < curr:
					if self.children[curr][0] is None:
						self.children[curr][0] = x
						self.children[x] = [None, None]
						self.parents[x] = curr
						self.splay(x)
						return None
					else:
						curr = self.children[curr][0]
				else:
					if self.children[curr][1] is None:
						self.children[curr][1] = x
						self.children[x] = [None, None]
						self.parents[x] = curr
						self.splay(x)
						return None
					else:
						curr = self.children[curr][1]

	def find(self, x):
		return x in self.parents

	def delete(self, x, show=False):
		if self.children[x][0] is None and self.children[x][1] is None:
			if self.root == x:
				self.root = None
			del self.children[x]
			p = self.parents[x]
			del self.parents[x]
			for i in range(2):
				if self.children[p][i] == x:
					self.children[p][i] = None
			self.splay(p)
		elif self.children[x][0] is None or self.children[x][1] is None:
			if self.children[x][0] is None:
				ind = 1
			else:
				ind = 0
			child = self.children[x][ind]
			if self.root == x:
				self.root = child
				del self.children[x]
				del self.parents[x]
				self.parents[child] = None
			else:
				p = self.parents[x]
				self.parents[child] = p
				for i in range(2):
					if self.children[p][i] == x:
						self.children[p][i] = child
				del self.parents[x]
				del self.children[x]
				self.splay(p)
		else:
			s = self.successor(x)
			if self.parents[s] == x:
				skids = self.children[s][:]
				xkid = self.children[x][0]
				xpar = self.parents[x]
				self.children[s] = [xkid, x]
				self.parents[s] = xpar
				self.children[x] = skids
				self.parents[x] = s
				for i in skids:
					if i is not None:
						self.parents[i] = x
				if xkid is not None:
					self.parents[xkid] = s
				if xpar is not None:
					for i in range(2):
						if self.children[xpar][i] == x:
							self.children[xpar][i] = s
				if self.root == x:
					self.root = s
