def bfs(n):
    result, a = [], []
    q = [(n, 1)]
    while q:
        new_q = []
        for n, coeff in q:
            if n <= 2:
                for i in xrange(1, n+1):
                    a.append(i*coeff)
                continue
            pw = 1<<(n.bit_length()-1)
            if pw == n:
                a.append(n*coeff)
                n -= 1
                pw //= 2
            a.append(pw*coeff)
            for i in xrange(1, (n-pw)+1):
                result.append(((pw-i)*coeff, (pw+i)*coeff))
                a.append(2*pw*coeff)
            new_q.append((pw-(n-pw)-1, coeff))
            new_q.append((n-pw, 2*coeff))
        q = new_q
    return result, a

def solution():
    n = int(raw_input())
    if n == 2:
        return -1
    result, a = bfs(n)
    a.sort()
    expect_num = 1<<(n-1).bit_length()
    for i in xrange(len(a)-1):
        if a[i] != a[i+1]:
            continue
        result.append((a[i], a[i+1]))
        a[i+1] += a[i]
        a.remove(a[i])
        break
    for x in a:
        while x != expect_num:
            result.append((0, x))
            result.append((x, x))
            x *= 2
    result.append((0, expect_num))
    return "%s\n%s" % (len(result), "\n".join(map(lambda x: " ".join(map(str, x)), result)))

