def merge(a,b):
    A=len(a)
    B=len(b)
    m=[]
    i,j=0,0
    while i<A and j<B:
        ai,bj=a[i],b[j]
        if ai<=bj:
            m.append(ai)
            i+=1
        else:
            m.append(b[j])
            j+=1
    m=m+a[i:A]+b[j:B]
    return m

