def work(n, k, points, row, col, explosion_time):
    pas = list(range(n))

    for x in row:
        ps = []
        for i in row[x]:
            px, py = points[i]
            ps.append([py, px, i])

        ps.sort()
        for i in range(len(ps) - 1):
            dist = abs(ps[i][0] - ps[i + 1][0])
            if dist <= k:
                union(pas, ps[i][2], ps[i + 1][2])

    for y in col:
        ps = []
        for i in col[y]:
            px, py = points[i]
            ps.append([px, py, i])
        ps.sort()
        for i in range(len(ps) - 1):
            dist = abs(ps[i][0] - ps[i + 1][0])
            if dist <= k:
                union(pas, ps[i][2], ps[i + 1][2])
    
    mint = defaultdict(int)
    for i in range(n):
        fi = find(pas, i)
        time = explosion_time[i]
        if fi not in mint:
            mint[fi] = time 
        else:
            mint[fi] = min(mint[fi], time)
    nodes = []
    for fa, time in mint.items():
        nodes.append([time, fa])
    nodes.sort()
    ans = 0 
    nodes.pop()
    while nodes:
        time, fa = nodes.pop()
        if time > ans:
            ans += 1 
    return ans 


