class Graph:
    def __init__(self,n,m,edge,tot):
        self.n=n
        self.m=m
        self.edge=edge
        self.tot=tot
        self.par=[-1 for _ in range(n+1)]
    
    def findParent(self,x,c1):
        if self.par[x]==-1:return x,c1
        else:return self.findParent(self.par[x],c1+1)

    def union(self,x,y):
        par1,c1=self.findParent(x,0)
        par2,c2=self.findParent(y,0)
        if par1==par2:return
        else:
            if c1>=c2:self.par[par2]=par1
            else:self.par[par1]=par2
            return
        
    def isPossible(self):
        for u,v,w in self.edge:
            if self.tot|w==self.tot:
                self.union(u,v)
        c=0
        for i in range(1,self.n+1):
           if self.par[i]==-1:c+=1
        if c>1:return False
        else:return True 
        
