class TrieNode:
	def __init__(self):
		self.count=0
		self.child={}
		self.end=False

class Trie:
	def __init__(self):
		self.node=TrieNode()

	def insert(self, word):
		root=self.node
		for char in word:
			if char not in root.child:
				root.child[char]=TrieNode()
			root=root.child[char]
			root.count+=1
		root.end=True

	def search(self, key):
		root=self.node
		for char in key:
			if char not in root.child:
				return False
			root=root.child[char]
		return root.end









