class FastIO:

	@classmethod
	def input(cls):
		from sys import stdin
		x = stdin.buffer.readline().decode().strip()
		return x

	@classmethod
	def integer_list(cls):
		return list(map(int, cls.input().split()))

	@classmethod
	def print(cls, s, end = "\n"):
		from sys import stdout
		stdout.write(str(s) + end)

	@classmethod
	def flush(cls):
		from sys import stdout
		stdout.flush()


