        delta = asin(R/d)
        angle = atan2(p[j][1]-p[i][1], p[j][0]-p[i][0])
        l, r = angle-delta, angle+delta
        if l > right:
            l, r = l-2*PI, r-2*PI
        elif r < left:
            l, r = l+2*PI, r+2*PI
        left, right = max(left, l), min(right, r)
        if left > right:
            return
    for j in range(len(p)):
        if j == i:
            continue
        angle = atan2(p[j][1]-p[i][1], p[j][0]-p[i][0])
        if angle > right:
            angle -= 2*PI
        elif angle < left:
            angle += 2*PI
        if left <= angle <= right:
            dp[i][j] = 1

