# Find the previous greater element for every element in a list
def findPrevGreaterOrEqual(arr):
    # base case
    if not arr:
        return []

    # create an empty stack
    s = list()
    ans = []

    # do for each element
    for i in range(len(arr)):
        # loop till stack is empty
        while s:
            # If the stack's top element is greater or equal than the current element,
            # it is the previous greater or equal element
            if arr[s[-1]] >= arr[i]:
                ans.append(s[-1])
                break
            # remove the stack's top element is less if it is lower or equal
            # to the current element
            else:
                s.pop()

        # If the stack becomes empty, all elements to the left
        # of the current element are lower
        if not s:
            ans.append(-1)

        # push current element into the stack
        s.append(i)

    return ans


# check if array is sorted
def is_sorted(arr):
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False
    return True


def solve():
    n = int(input())
    s = [bool(int(x)) for x in input()]

    # if the number of zeros is greater than the number of ones, we swap the problem
    b = 0
    for i in range(n):
        if s[i]:
            b += 1
        else:
            b -= 1

    if b < 0:
        s = [not x for x in s]
        s.reverse()

    # change 0's to -1's
    cs = [1 if x else -1 for x in s]

    # build the array of prefixes
    pref = [0] * (n + 1)
    for i in range(1, n + 1):
        pref[i] = pref[i - 1] + cs[i - 1]

    # find the previous greater or equal elem for every index in the array of prefixes
    prev = findPrevGreaterOrEqual(pref)

    # locate `i` where the first iteration should take place
    i = n
    while i > 0 and pref[i] > pref[i - 1]:
        i -= 1

    # find `j` for that `i`
    j = i - 1
    for k in range(i, -1, -1):
        # this is the smallest index with value equal to pref[i] so we can break the loop
        if pref[k] == pref[i] and prev[k] == -1:
            j = k
            break

    ans = 0
    # while pref[i] > 0 we cant sort in one operation of balance 0
    while pref[i] > 0:
        ans += 1

        # sort [j,i] and fix pref
        for k in range(j + 1, (i + j) // 2 + 1):
            s[k - 1] = False
            pref[k] = pref[j] - (k - j)

        for k in range((i + j) // 2 + 1, i + 1):
            s[k - 1] = True
            pref[k] = pref[j] + (k - ((i + j) // 2))

        # move i to its new position
        i -= 1
        while i > 0 and pref[i] > pref[i - 1]:
            i -= 1

        # move j to its new position as well
        for k in range(j - 1, -1, -1):
            if pref[k] == pref[i] and prev[k] == -1:
                j = k
                break

    if is_sorted(s):
        print(ans)
    else:
        print(ans + 1)


