class BIT(object):
    def __init__(self, n):
        self.__bit = [0]*(n+1)

    def add(self, i, val):
        while i < len(self.__bit):
            self.__bit[i] += val
            i += (i & -i)

    def query(self, i):
        ret = 0
        while i > 0:
            ret += self.__bit[i]
            i -= (i & -i)
        return ret

    def search(self, val):
        floor_log2_n = (len(self.__bit)-1).bit_length()-1
        pow_i = 2**floor_log2_n
        total = pos = 0
        for _ in reversed(range(floor_log2_n+1)):
            if pos+pow_i < len(self.__bit) and total+self.__bit[pos+pow_i] < val:
                total += self.__bit[pos+pow_i]
                pos += pow_i
            pow_i >>= 1
        return pos

def solution():
    n, m, q = list(map(int, input().strip().split()))
    arr = list(map(int, input().strip().split()))
    brr = list(map(int, input().strip().split()))
    for i in reversed(range(1, n)):
        arr[i] -= arr[i-1]
    for i in reversed(range(1, m)):
        brr[i] -= brr[i-1]
    curr = (arr[0]+brr[0])*(n+m-1)+sum(brr[i]*(m-i) for i in range(1, m))
    bit1, bit2, bit3 = BIT(m), BIT(m), BIT(m)
    for i in range(1, m):
        bit1.add(i, brr[i])
        bit1.add(i+1, -brr[i])
        bit2.add(i, brr[i])
    bit1.add(m, float("inf"))
    result = []
    for _ in range(q):
        a, b, c = list(map(int, input().strip().split()))
        if a == 1:
            for i in range(b):
                arr[i+(n-b)] += c
            if b == n:
                curr += c*(n+m-1)
        else:
            if b == m:
                curr += c*(n+m-1)
                b -= 1
            curr += (b)*(b+1)//2*c
            bit1.add(m-b, c)
            bit3.add(m-b, c)
            bit2.add(m-b, -c*(m-b-1))
        ans = curr
        for i in range(1, n):
            idx = bit1.search(arr[i])
            ans += bit3.query(idx)*idx+bit2.query(idx)
            ans += arr[i]*(n+m-i-idx-1)
        result.append(ans)
    return "\n".join(map(str, result))

