import random

def FindSet(dsu, x):
	if dsu[x] != x:
		dsu[x] = FindSet(dsu, dsu[x])
	return dsu[x]

def Unite(dsu, x, y):
	x = FindSet(dsu, x)
	y = FindSet(dsu, y)
	if random.random() > 0.5:
		dsu[x] = y
	else:
		dsu[y] = x

