def sieve(s):
	is_not_prime=[False]*(s+1)
	prime=[]
	small=[0]*(s+1)
	cnt=[0]*(s+1)
	other=[0]*(s+1)
	for i in xrange(2, s+1):
		if not is_not_prime[i]:
			prime.append(i)
			small[i]=i
			cnt[i]=1
			other[i]=1
		for p in prime:
			next=p*i
			if next>s:
				break
			is_not_prime[next]=True
			small[next]=p
			if i%p==0:
				cnt[next]=cnt[i]+1
				other[next]=other[i]
				break
			cnt[next]=1
			other[next]=i
	print>>sys.stderr, len(prime)
