def get_max_objects(s, m, k):
    low = 0
    high = len(s)
    while low < high:
        mid = (low + high) // 2
        if can_fit(s, mid, m, k):
            high = mid
        else:
            low = mid + 1
    return len(s) - low

def can_fit(s, start, m, k):
    left = 0
    for i in range(start, len(s)):
        if left < s[i]:
            if m == 0:
                return False
            m -= 1
            left = k
        left -= s[i]
    return True

